# Generates test/scipy/test_stats_final_levy.py with scipy 1.18.1.
import numpy as np, scipy.stats as st
def L(a): return repr([float(v) for v in np.ravel(a)])
xs = [-3.0, -1.0, -0.2, 0.0, 0.4, 1.5, 4.0]
o = ["# Copyright (C) 2026 the Typhon authors",
"# Expected values generated by test/scipy/gen_stats_final_levy.py (scipy 1.18.1).",
"import numpy as np", "import scipy.stats as st", "",
"def close(a, b, rtol: float = 1e-7) -> bool:",
"    x = np.asarray(a).astype(float).ravel()", "    y = np.asarray(b).astype(float).ravel()",
"    if x.shape != y.shape:", "        return False",
"    for i in range(x.shape[0]):",
"        u = float(x[i])", "        v = float(y[i])",
"        if not (abs(u - v) <= 1e-10 + rtol * abs(v) or (u != u and v != v)):",
"            print('mismatch', i, u, v)", "            return False",
"    return True", "", f"xs = {xs}", ""]
for tag, a, b in [('a', 1.6, 0.4), ('b', 0.7, -0.5), ('c', 1.0, 0.3), ('d', 2.0, 0.0), ('e', 0.5, 1.0)]:
    d = st.levy_stable
    o += [f"@test", f"def test_levy_{tag}():",
          f"    assert close(st.levy_stable.pdf(xs, {a}, {b}), {L(d.pdf(xs, a, b))})",
          f"    assert close(st.levy_stable.cdf(xs, {a}, {b}), {L(d.cdf(xs, a, b))})",
          f"    assert close(st.levy_stable.pdf(xs, {a}, {b}, loc=0.5, scale=2.0), {L(d.pdf(xs, a, b, loc=0.5, scale=2.0))})",
          f"    assert close(st.levy_stable.rvs({a}, {b}, size=5, random_state=np.random.RandomState(3)), {L(d.rvs(a, b, size=5, random_state=np.random.RandomState(3)))}, 1e-9)", ""]
print("\n".join(o))
